import{_ as e,o as r,c as l,ae as o}from"./chunks/framework.DFTT1zkb.js";const u=JSON.parse('{"title":"远程连接","description":"","frontmatter":{},"headers":[],"relativePath":"remote-connection.md","filePath":"remote-connection.md"}'),i={name:"remote-connection.md"};function t(n,a,h,d,c,s){return r(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="远程连接" tabindex="-1">远程连接 <a class="header-anchor" href="#远程连接" aria-label="Permalink to &quot;远程连接&quot;">​</a></h1><h2 id="公网ip机器" tabindex="-1">公网IP机器 <a class="header-anchor" href="#公网ip机器" aria-label="Permalink to &quot;公网IP机器&quot;">​</a></h2><p>对于已有公网IP的机器，比如云主机 NAT VPS，放行本地防火墙的7799端口，放行/映射7799端口到公网，即可直接远程访问web面板</p><h2 id="内网穿透" tabindex="-1">内网穿透 <a class="header-anchor" href="#内网穿透" aria-label="Permalink to &quot;内网穿透&quot;">​</a></h2><p>windowOP内置了两种内网穿透方案：</p><h3 id="sakurafrp-推荐" tabindex="-1">SakuraFrp(推荐) <a class="header-anchor" href="#sakurafrp-推荐" aria-label="Permalink to &quot;SakuraFrp(推荐)&quot;">​</a></h3><p>SakuraFrp是一个免费的内网穿透服务，使用简单，配置方便。</p><h4 id="特点" tabindex="-1">特点 <a class="header-anchor" href="#特点" aria-label="Permalink to &quot;特点&quot;">​</a></h4><ul><li><strong>简单易用</strong>：只需输入配置Token</li><li><strong>免费服务</strong>：提供免费的隧道服务</li><li><strong>稳定可靠</strong>：服务质量稳定</li><li><strong>自动重连</strong>：网络中断后自动重连</li></ul><h4 id="配置方法" tabindex="-1">配置方法 <a class="header-anchor" href="#配置方法" aria-label="Permalink to &quot;配置方法&quot;">​</a></h4><ol><li>进入<a href="https://www.sakurafrp.com/" target="_blank" rel="noreferrer">樱花映射</a>注册一个账号并创建一个隧道，隧道类型tcp，本地端口7799，远程端口随机即可，<em>自动 HTTPS打开</em>，没有使用过的建议查看网上的教程</li><li>在<a href="https://www.sakurafrp.com/tunnel/" target="_blank" rel="noreferrer">隧道列表</a>中查看隧道配置文件并复制（格式：<code>-f abcdefghijkl:12345678</code>）</li><li>进入「设置」→「远程控制」→「公网服务」</li><li>选择「SakuraFrp」打开，把复制的配置信息填入「Frpc 启动参数」中</li><li>在浏览器中输入该隧道对外的公网IP和端口，即可访问内网设备的web面板了</li></ol><h3 id="也可以选择自建frp-需要网络通信基础知识-一台公网ip机器" tabindex="-1">也可以选择自建Frp(需要网络通信基础知识，一台公网IP机器) <a class="header-anchor" href="#也可以选择自建frp-需要网络通信基础知识-一台公网ip机器" aria-label="Permalink to &quot;也可以选择自建Frp(需要网络通信基础知识，一台公网IP机器)&quot;">​</a></h3><h4 id="配置方法-1" tabindex="-1">配置方法 <a class="header-anchor" href="#配置方法-1" aria-label="Permalink to &quot;配置方法&quot;">​</a></h4><h5 id="服务端" tabindex="-1">服务端 <a class="header-anchor" href="#服务端" aria-label="Permalink to &quot;服务端&quot;">​</a></h5><ol><li>需要一台有公网IP的机器，下载<a href="https://gitee.com/lmx12330/window-op/tree/master/res" target="_blank" rel="noreferrer">Gitee仓库</a>中的<code>frps.exe</code>和<code>frps.toml</code>(注意名字不要下成frpc)</li><li>打开<code>frps.toml</code>文件，修改<code>auth.token</code>和<code>webServer.password</code>为合适的Token和密码</li><li>保存文件，运行<code>frps.exe</code>启动服务端</li><li>放行<code>bindPort</code>端口到公网(防火墙与云服务商都需要放行)</li><li>(可选) 放行<code>webServer.port</code>端口到公网(适用于无法远程桌面云主机)</li></ol><h5 id="客户端" tabindex="-1">客户端 <a class="header-anchor" href="#客户端" aria-label="Permalink to &quot;客户端&quot;">​</a></h5><ol><li>进入「设置」→「远程控制」→「公网服务」</li><li>选择「通用Frpc」，输入服务端IP，端口，Token，名称</li></ol><h5 id="最后步骤" tabindex="-1">最后步骤 <a class="header-anchor" href="#最后步骤" aria-label="Permalink to &quot;最后步骤&quot;">​</a></h5><ol><li>在服务端浏览器/远程浏览器访问<code>webServer.port</code>端口，进入frps管理面版，查看连接到了哪个端口</li><li>直接在服务端访问映射后端口或映射该端口到公网后访问，即可访问客户端的web面板</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="q-连接失败" tabindex="-1">Q: 连接失败 <a class="header-anchor" href="#q-连接失败" aria-label="Permalink to &quot;Q: 连接失败&quot;">​</a></h3><p><strong>A:</strong> 请检查以下几点：</p><ul><li>Frp服务端是否正常运行</li><li>网络连接是否正常</li><li>配置信息是否正确</li><li>防火墙是否允许连接</li></ul><h3 id="q-访问速度慢" tabindex="-1">Q: 访问速度慢 <a class="header-anchor" href="#q-访问速度慢" aria-label="Permalink to &quot;Q: 访问速度慢&quot;">​</a></h3><p><strong>A:</strong> 请检查以下几点：</p><ul><li>网络带宽是否足够</li><li>Frp服务端性能是否足够</li><li>客户端和服务端之间的网络延迟</li></ul><h3 id="q-连接不稳定" tabindex="-1">Q: 连接不稳定 <a class="header-anchor" href="#q-连接不稳定" aria-label="Permalink to &quot;Q: 连接不稳定&quot;">​</a></h3><p><strong>A:</strong> 请检查以下几点：</p><ul><li>网络连接是否稳定</li><li>Frp服务端是否稳定</li><li>客户端和服务端之间的网络质量</li></ul>',29)])])}const f=e(i,[["render",t]]);export{u as __pageData,f as default};
